/// View over multiple NumericsRestart with field accumulation
pub struct NumericsRestartSliceView<'a, D> {
    pub time: Accumulator<'a, NumericsRestart, FLT_0D, D>,
    slice_elements: Elements<'a, NumericsRestart, D>,
}

impl<'a, D: Dimension> NumericsRestartSliceView<'a, D> {
    pub fn new(elements: Elements<'a, NumericsRestart, D>) -> Self {
        Self {
            time: Accumulator::new(elements.clone(), |item: &NumericsRestart| item.time),
            slice_elements: elements,
        }
    }

    /// Total number of elements, across every sliced level
    pub fn len(&self) -> usize {
        self.slice_elements.len()
    }

    pub fn is_empty(&self) -> bool {
        self.slice_elements.is_empty()
    }

    /// The length of each sliced level, in path order like the gathered arrays
    pub fn shape(&self) -> Vec<usize> {
        self.slice_elements.shape()
    }

    /// Every element, in path order: the first array of structures on the path varies slowest
    pub fn iter(&self) -> impl Iterator<Item = &'a NumericsRestart> + '_ {
        self.slice_elements.iter()
    }
}

impl ArrayOfStructuresElement for NumericsRestart {
    type SliceView<'a, D>
        = NumericsRestartSliceView<'a, D>
    where
        Self: 'a;

    fn slice_view<'a, D: Dimension>(elements: Elements<'a, Self, D>) -> Self::SliceView<'a, D>
    where
        Self: 'a,
    {
        NumericsRestartSliceView::new(elements)
    }
}

