impl NumericsBcGgdElectrons {
    /// Select from `particles`. A range, e.g. `.particles(0..2)` or `.particles(..)`, gives the slice view over
    /// those elements, whose leaves gather one value per element.
    /// A single element is `.particles[i]`.
    ///
    /// # Panics
    /// If a range is out of bounds.
    pub fn particles<'a, S: Selection<'a, NumericsBcGgdBc>>(&'a self, selection: S) -> S::Output {
        selection.select("particles", &self.particles)
    }

    /// Get the number of particles elements
    pub fn particles_len(&self) -> usize {
        self.particles.len()
    }
}

